/* === 全局背景色设置 === */
:root {
    --chat-bg-color: #8BACD9;
}
/* 直接覆盖聊天区域背景 */
.chat-detail-screen,
.chat-messages-area,
[data-theme-style="plain"] .chat-messages-area {
    background-color: #8BACD9 !important;
}
/* === 1. 基础颜色与布局 (已按新要求更新) === */
:root {
    /* 我方气泡颜色和圆角 */
    --bubble-me-bg: #6DE77A;
    --bubble-me-color: #000000;
    --bubble-me-radius: 18px;
    /* 对方气泡颜色和圆角 */
    --bubble-them-bg: #FFFFFF;
    --bubble-them-color: #000000;
    --bubble-them-radius: 18px;

    /* 连续气泡间的微小间距 */
    --plain-gap-within-group: 4px;
    /* 其他布局保持不变 */
    --plain-gap-between-groups: 16px;
    --plain-avatar-radius: 10px;
    --plain-avatar-size: 36px;
}
/* === 2. 头像显示逻辑 (只在第一条显示) === */
/* 默认隐藏所有头像容器 */
.msg-avatar-them-container,
.msg-avatar-me-container {
    visibility: hidden;
    width: 0;
}
/* 只在“第一条” (is-first) 或 “单条” (is-single) 时显示头像 */
.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single,
.msg-avatar-me-container.is-first,
.msg-avatar-me-container.is-single {
    visibility: visible;
    width: var(--plain-avatar-size);
}
/* === 3. 气泡小尾巴 (终极增强版) === */
/* 确保气泡容器允许内容溢出，并且为伪元素提供定位参考 */
.bubble-me-custom,
.bubble-them-custom { 
    position: relative !important; 
    overflow: visible !important; 
}
/* 移除消息边框 */
.bubble-me-custom,
.bubble-them-custom {
  border: none !important;
  outline: none !important;
  box-shadow: none !important;
}
/* 对方气泡小尾巴 (白色) */
.msg-them.is-first .bubble-them-custom::before,
.msg-them.is-single .bubble-them-custom::before {
    content: "" !important;
    display: block !important;
    position: absolute !important;
    background-image: url('https://img.heliar.top/file/1775967946804_retouch_2026041212252435.png?v=1') !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    z-index: 2 !important;

    /* 调整大小和位置 */
    width: 12px;
    height: 17px;
    left: -7px;
    top: 1px;
}
/* 我方气泡小尾巴 (绿色) */
.msg-me.is-first .bubble-me-custom::before,
.msg-me.is-single .bubble-me-custom::before {
    content: "" !important;
    display: block !important;
    position: absolute !important;
    background-image: url('https://img.heliar.top/file/1775967595992_retouch_2026041212192143.png?v=1') !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    z-index: 2 !important;
    /* 调整大小和位置 */
    width: 12px;
    height: 17px;
    right: -5px;
    top: 1px;
}
/* === 4. 缩小气泡整体尺寸 === */
:root {
    --bubble-me-padding: 7px 12px;
    --bubble-them-padding: 7px 12px;
    --bubble-me-font-size: 14px;
    --bubble-them-font-size: 14px;
    --bubble-me-line-height: 1.4;
    --bubble-them-line-height: 1.4;
}
/* === 5. 已读状态/时间戳样式（IG风格） === */
/* ===== 状态时间 - 每条都显示，放在气泡左侧外部下角 ===== */
/* 确保每条消息都显示状态 */
.msg-me .msg-status-custom,
.msg-me.is-first .msg-status-custom,
.msg-me.is-mid .msg-status-custom,
.msg-me.is-last .msg-status-custom,
.msg-me.is-single .msg-status-custom {
    display: block !important;
    visibility: visible !important;

    /* 绝对定位 - 相对于消息行容器 */
    position: absolute !important;

    /* 放在气泡左侧外部 */
    left: 0 !important;
    bottom: 0 !important;          /* 与气泡底部对齐 */

    /* 移到气泡外面 */
    transform: translateX(-100%) translateY(0) !important;

    /* 文字样式 */
    font-size: 10px !important;
    color: rgba(0, 0, 0, 0.4) !important;
    white-space: nowrap !important;

    /* 与气泡的间距 */
    margin-right: 6px !important;   /* 气泡左边外侧的间距 */
    padding-right: 4px !important;
}
/* 消息行容器需要设置相对定位 */
.msg-me {
    position: relative !important;
}
/* 气泡内容容器 */
.msg-me .msg-content-stack {
    position: relative !important;
}
/* 如果上面的 left: 0 定位不准，用这个 */
.msg-me .msg-status-custom {
    left: -10px !important;         /* 负值越大越靠左 */
    bottom: 2px !important;         /* 微调上下位置 */
    transform: translateX(-100%) !important;  /* 完全移到气泡左侧 */
}

