/* 返回数字横向椭圆背景 */
.header-btn-back::after {
    background: rgba(208, 235, 237, 0.8) !important;
    color: #fff !important;
    border-radius: 50px !important;
    width: 32px !important;
    height: 18px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    line-height: 1 !important;
    padding: 0 !important;
}


/* ==========================================
   正在输入
   ========================================== */
.msg-them .typing-indicator,
.msg-them [class*="typing-bubble"],
.msg-them [class*="typing"] [class*="bubble"],
.typing-bg,
[class*="typing-bg"] {
    background: transparent !important;
    box-shadow: none !important;
    border: none !important;
    padding: 0 !important;
}

.typing-dot,
[class*="typing-dot"] {
    width: 8px !important;
    height: 8px !important;
    border-radius: 50% !important;
    transform: translateY(18px) !important; /* ↑ 三个点上下位移 */
    max-width: 8px !important;
    min-width: 8px !important;
}


.chat-detail-screen > div:nth-child(2) {
  position: relative !important;
  margin: 40px 15px 90px 15px !important; /* ↑ 卡片外边距：上 左右 下 */
  background: linear-gradient(
    to bottom,
    rgba(250, 250, 250, 1) 0%,
    rgba(250, 250, 250, 1) 40%,
    rgba(250, 250, 250, 0) 100%
  ) !important;
  border-radius: 24px !important;
  box-shadow:
    0 -18px 0 -3px rgba(255, 255, 255, 0.35),
    0 -38px 0 -10px rgba(255, 255, 255, 0.2),
    0 10px 20px rgba(0, 0, 0, 0.15) !important;
  flex: 1 !important;
  height: auto !important;
}

/* ==========================================
   ios18语音消息
   ========================================== */

/* 隐藏语音转文字按钮 */
.voice-transcription-toggle {
    position: absolute !important;
    right: 40px !important;
    top: 50% !important;
    transform: translateY(-50%) !important;
    opacity: 0 !important;
    pointer-events: auto !important;
    z-index: 2 !important;
    width: 20px !important;
    height: 20px !important;
}
.voice-transcription-toggle svg,
.voice-download-btn svg {
    display: none !important;
}

/* 隐藏下载按钮 */
.voice-download-btn {
    opacity: 0 !important;
    pointer-events: auto !important;
    width: 20px !important;
    height: 20px !important;
}

/* 播放按钮通用 */
.voice-play-btn {
    width: 28px !important;
    height: 28px !important;
    min-width: 28px !important;
    min-height: 28px !important;
    border-radius: 50% !important;
    border: none !important;
    box-shadow: none !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    flex-shrink: 0 !important;
    margin-right: 4px !important;
}
.voice-play-btn:active {
    transform: scale(0.92) !important;
    opacity: 0.8 !important;
}
.voice-play-btn svg {
    width: 14px !important;
    height: 14px !important;
}

/* 控件行 */
.voice-controls-row {
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    gap: 4px !important;
    transform: translateY(0px) !important; /* ↑ 控件行上下位移 */
    position: relative !important;
}

/* 波形条 */
.voice-waveform {
    flex: 1 !important;
    max-width: none !important;
    width: 100% !important;
    padding-right: 40px !important;
    box-sizing: border-box !important;
}

/* 时间戳 */
.voice-duration {
    position: absolute !important;
    right: -8px !important; /* ↑ 时间戳左右位置 */
    font-size: 13px !important;
    font-weight: 500 !important;
    flex-shrink: 0 !important;
}

.voice-msg-me,
.voice-msg-them {
    position: relative !important;
}

/* 我方语音 */
.voice-msg-me .voice-play-btn {
    background: #ecf7f8 !important;
}
.voice-msg-me .voice-play-btn svg {
    color: #262626 !important;
    fill: #262626 !important;
    stroke: #262626 !important;
}
.voice-msg-me .voice-waveform-bar {
    background: #262626 !important;
}
.voice-msg-me .voice-duration {
    color: #262626 !important;
}

/* 对方语音 */
.voice-msg-them .voice-play-btn {
    background: #262626 !important;
}
.voice-msg-them .voice-play-btn svg {
    color: #ecf7f8 !important;
    fill: #ecf7f8 !important;
    stroke: #ecf7f8 !important;
}
.voice-msg-them .voice-waveform-bar {
    background: #262626 !important;
}
.voice-msg-them .voice-duration {
    color: #262626 !important;
}

/* ==========================================
   气泡
   ========================================== */

/* 间距 */
:root {
  --chat-messages-gap: 12px;
}

/* 我方气泡 */
:root {
  --bubble-me-bg: #ffffff;
  --bubble-me-color: #262626;
  --bubble-me-border: 0.8px solid #D0EBED;
  --bubble-me-padding: 6px 16px;
  --bubble-me-font-size: 16px;
  --bubble-me-radius: 20px;
  --bubble-me-radius-first: 20px 20px 4px 20px;
  --bubble-me-radius-mid: 20px 4px 4px 20px;
  --bubble-me-radius-last: 20px 4px 20px 20px;
}

/* 对方气泡 */
:root {
  --bubble-them-bg: #ecf7f8;
  --bubble-them-color: #262626;
  --bubble-them-border: none;
  --bubble-them-padding: 6px 16px;
  --bubble-them-font-size: 16px;
  --bubble-them-radius: 20px;
  --bubble-them-radius-first: 20px 20px 20px 4px;
  --bubble-them-radius-mid: 4px 20px 20px 4px;
  --bubble-them-radius-last: 4px 20px 20px 20px;
}

/* 对方头像只在第一条显示 */
.msg-avatar-them-container { display: none !important; }

.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single {
  display: flex !important;
  visibility: visible !important;
  opacity: 1 !important;
}

/* 我方头像隐藏 */
.msg-avatar-me-container { display: none !important; }

/* 头像强制圆形 */
.msg-avatar-them-inner,
.msg-avatar-them-container img {
  border-radius: 50% !important;
  overflow: hidden !important;
}

/* 隐藏隐形触控区 */
.msg-avatar-them-ghost { display: none !important; }

/* 对方头像 absolute 提到气泡上方 */
.msg-them .msg-avatar-them-container.is-first,
.msg-them .msg-avatar-them-container.is-single {
  position: relative !important;
}

.msg-them .msg-avatar-them-container.is-first .msg-avatar-them-inner,
.msg-them .msg-avatar-them-container.is-single .msg-avatar-them-inner {
  position: absolute !important;
  top: -48px !important; /* ↑ 头像上下位置 */
  left: 0 !important;
  overflow: visible !important;
}

/* 第一条消息顶部留空间 */
.msg-them.msg-bubble-wrapper.is-first,
.msg-them.msg-bubble-wrapper.is-single {
  margin-top: 54px !important; /* ↑ 有头像的消息顶部间距 */
  margin-left: 0 !important;
  padding-left: 0 !important;
}

.msg-them .msg-avatar-them-container.is-first,
.msg-them .msg-avatar-them-container.is-single {
  width: 0 !important;
  height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* 头像右侧 ID */
.msg-them .msg-avatar-them-container.is-first::after,
.msg-them .msg-avatar-them-container.is-single::after {
  content: "@role_id"; /* ↑ 改这里的文字🩶 */
  position: absolute;
  top: -48px; /* ↑ ID上下位置（与头像top保持一致） */
  left: 48px; /* ↑ ID左右位置 */
  white-space: nowrap;
  font-size: 11px;
  font-weight: 400;
  color: #6b7280;
  letter-spacing: 0.3px;
  line-height: 1.5;
  padding-right: 20px;
}

/* ID右边小图标 */
.msg-them .msg-avatar-them-container.is-first::before,
.msg-them .msg-avatar-them-container.is-single::before {
  content: "";
  position: absolute;
  top: -48px; /* ↑ 小图上下位置 */
  left: calc(48px + 48px); /* ↑ 小图左右位置 */
  width: 16px;
  height: 16px;
  background-image: url("https://i.postimg.cc/445YLFK1/IMG-4310.png");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  border-radius: 4px;
  pointer-events: none;
  z-index: 5;
}

/* 头像下方文案 */
.msg-them .msg-avatar-them-container.is-first .msg-avatar-them-inner::after,
.msg-them .msg-avatar-them-container.is-single .msg-avatar-them-inner::after {
  content: "🤍"; /* ↑ 改这里的文字🩶 */
  position: absolute;
  top: 20px; /* ↑ 文案上下位置 */
  left: calc(100% + 8px); /* ↑ 文案左右位置 */
  font-size: 11px;
  font-weight: 400;
  color: #6b7280;
  letter-spacing: 0.3px;
  line-height: 1.5;
  white-space: nowrap;
  pointer-events: none;
}

/* 气泡间距 */
.msg-bubble-wrapper {
    margin-bottom: 8px !important;
}

.msg-bubble-wrapper.is-first,
.msg-bubble-wrapper.is-mid {
    margin-bottom: 8px !important;
}

.msg-bubble-wrapper.is-last,
.msg-bubble-wrapper.is-single {
    margin-bottom: 16px !important;
}

/* =============================================
   底栏
   ============================================= */
.input-area-custom {
    position: absolute !important;
    bottom: 0 !important;
    left: 0 !important;
    right: 0 !important;
    z-index: 60 !important;
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border-top: none !important;
    padding: 8px 12px 8px 12px !important; /* ↑ 底栏内边距：上 左右 下 */
    padding-bottom: max(8px, var(--nuo-safe-bottom)) !important;
    overflow: visible !important;
    transform: none !important;
}

.input-area-custom::before,
.input-area-custom::after {
    display: none !important;
    content: none !important;
}

.input-row-wrapper {
    display: flex !important;
    flex-direction: row !important;
    align-items: flex-end !important;
    gap: 10px !important; /* ↑ 按钮和输入框间距 */
    position: relative !important;
    z-index: 10 !important;
    margin-bottom: 0 !important;
}

/* 加号按钮 */
.input-btn-plus {
    position: relative !important;
    background: rgba(255, 255, 255, 0.5) !important;
    backdrop-filter: blur(20px) saturate(100%) !important;
    -webkit-backdrop-filter: blur(20px) saturate(100%) !important;
    border: none !important;
    border-radius: 50% !important;
    width: 36px !important;
    height: 36px !important;
    bottom: -6px !important; /* ↑ 加号按钮上下偏移 */
    min-width: 34px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    margin: 0 !important;
    flex-shrink: 0 !important;
    cursor: pointer !important;
    overflow: hidden !important;
    box-shadow:
        inset 1px 1px 0 0 rgba(255, 255, 255, 0.6),
        inset -1px -1px 0 0 rgba(255, 255, 255, 0.3),
        0 4px 12px rgba(0, 0, 0, 0.08),
        0 2px 4px rgba(0, 0, 0, 0.04) !important;
    transform: translateZ(0) !important;
}
.input-btn-plus > * {
    position: relative !important;
    z-index: 1 !important;
}
.input-btn-plus:active {
    background: rgba(255, 255, 255, 0.65) !important;
    transform: scale(0.92) translateZ(0) !important;
    box-shadow:
        inset 1px 1px 0 0 rgba(255, 255, 255, 0.4),
        0 2px 6px rgba(0, 0, 0, 0.06) !important;
}
.input-btn-plus svg {
    width: 24px !important;
    height: 24px !important;
    color: #3d3a40 !important;
    stroke: #3d3a40 !important;
    stroke-width: 1.8 !important;
}

/* 输入胶囊 */
.input-action-bar-custom {
    flex: 1 !important;
    margin-right: 5px !important; /* ↑ 胶囊右侧间距 */
    transform: translateY(8px) translateZ(0) !important; /* ↑ 胶囊整体上下偏移 */
    background: rgba(255, 255, 255, 0.5) !important;
    backdrop-filter: blur(20px) saturate(100%) !important;
    -webkit-backdrop-filter: blur(20px) saturate(100%) !important;
    border: 0.5px solid rgba(255, 255, 255, 0.3) !important;
    border-radius: 28px !important;
    padding: 0px 12px 0px 8px !important; /* ↑ 胶囊内边距 */
    min-height: 38px !important;
    height: 38px !important;
    max-height: 38px !important;
    display: flex !important;
    align-items: center !important;
    gap: 8px !important;
    overflow: hidden !important;
    box-shadow:
        inset 1px 1px 0 0 rgba(255, 255, 255, 0.6),
        inset -1px -1px 0 0 rgba(255, 255, 255, 0.3),
        0 4px 12px rgba(0, 0, 0, 0.08),
        0 2px 4px rgba(0, 0, 0, 0.04) !important;
}
.input-action-bar-custom > * {
    position: relative !important;
    z-index: 1 !important;
}

.input-box-custom {
    flex: 1 !important;
    background: transparent !important;
    border: none !important;
    color: #000000 !important;
    font-size: 16px !important;
    font-weight: 400 !important;
    line-height: 38px !important;
    padding: 0 !important;
    margin: 0 !important;
    resize: none !important;
    outline: none !important;
    -webkit-text-fill-color: #000000 !important;
    caret-color: #000000 !important;
    overflow: hidden !important;
    white-space: nowrap !important;
    text-overflow: ellipsis !important;
    height: 38px !important;
}
.input-box-custom::placeholder {
    color: transparent !important;
    opacity: 0 !important;
}

/* 占位提示词 */
.input-action-bar-custom::before {
    content: "iMessage" !important; /* ↑ 改这里的提示文字🩶 */
    position: absolute !important;
    left: 14px !important; /* ↑ 提示词左右位置 */
    top: 50% !important;
    transform: translateY(-50%) !important;
    color: rgba(0, 0, 0, 0.25) !important;
    font-size: 14px !important;
    line-height: 1 !important;
    opacity: 1 !important;
    pointer-events: none !important;
    z-index: 10 !important;
}
.input-action-bar-custom:has(.input-box-custom:focus)::before,
.input-action-bar-custom:has(.input-box-custom:not(:empty))::before {
    display: none !important;
}

/* 右侧按钮组 */
.input-action-bar-custom > div:last-child {
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    gap: 6px !important; /* ↑ 右侧按钮间距 */
    flex-shrink: 0 !important;
    margin-right: -10px !important; /* ↑ 右侧按钮组整体左右偏移 */
}

/* 表情按钮 (order 1) */
.input-btn-sticker {
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    background: transparent !important;
    border: none !important;
    padding: 8px !important;
    margin: 0 !important;
    cursor: pointer !important;
    opacity: 0 !important;
    pointer-events: auto !important;
    width: 32px !important;
    height: 32px !important;
    order: 1 !important;
}
.input-btn-sticker:active {
    opacity: 0 !important;
}
.input-btn-sticker svg {
    opacity: 0 !important;
    width: 0 !important;
    height: 0 !important;
    display: none !important;
}

/* 语音按钮 (order 2) */
.input-btn-mic {
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
    margin: 0 !important;
    cursor: pointer !important;
    opacity: 0 !important;
    pointer-events: auto !important;
    transition: opacity 0.2s ease !important;
    order: 2 !important;
    width: 32px !important;
