    background: transparent !important;
}
.input-btn-ai svg {
    display: none !important;
}
.input-btn-ai::before {
    content: "" !important;
    display: block !important;
    width: 28px !important;
    height: 28px !important;
    background-image: url("https://i.postimg.cc/mrz9KNxF/IMG-4306.png") !important; /* ↑ AI按钮图标🩶 */
